 hnf:['CHEST / Raschke — exemplo de nomograma por TTPa','https://pmc.ncbi.nlm.nih.gov/articles/PMC3278070/'],
 hnfprep:['NSW CEC — concentração padrão de HNF, setembro/2026','https://cec.health.nsw.gov.au/therapeutics-safety/continuous-infusions/adult/heparin'],
 hnfmon:['South Tees NHS — monitorização de HNF','https://www.southtees.nhs.uk/services/pathology/tests/unfractionated-heparin-ufh/'],
 hnfcanada:['Thrombosis Canada — HNF e HBPM','https://thrombosiscanada.ca/guides/pdfs/UnfractionatedHeparin_Low_molecular_weight_heparin.pdf'],
 enox:['Sanofi — enoxaparina, bula profissional (revisão 05/2025)','https://products.sanofi.us/lovenox/lovenox.pdf'],
